def contar_grupos_desde(lista, i):
    """ list, int -> int
        OBJ: Recorre recursivamente desde el índice i contando grupos.
        Pre: 0 <= i < len(arr)
    """
    if len(lista) == 0:
        return 0
    elif i == len(lista) - 1:
        # El último elemento siempre cierra un grupo
        return 1
    elif lista[i] == lista[i + 1]:
        # Seguimos dentro del mismo grupo
        return contar_grupos_desde(lista, i + 1)
    else:
        # Cambio de valor: cerramos un grupo y sumamos 1
        return 1 + contar_grupos_desde(lista, i + 1)

