def fibonacci(n, calculados):
    """ int, dict -> long
        OBJ: término n de la serie de Fibonacci usando memoization
        pre: n>=0
    """
    if n <= 1:  return n
    else:
        if n not in calculados:
           calculados[n] = fibonacci(n-1, calculados) + fibonacci(n-2, calculados)
        return calculados[n]

